mapper.select:
SELECT ProdCode, ImgCode, ImgName, ImgDesc, ImgLrg, ImgMdm, ImgSml, State, Remark, RegistId, RegistName, RegistDate, ChangeId, ChangeName, ChangeDate FROM shopion.tPrdProdImg WHERE ProdCode = #{pProdCode}
UNION SELECT ProdCode, '000' AS ImgCode, '기본' AS ImgName, '기본' AS ImgDesc, ImgUrl AS ImgLrg, ImgUrl280 AS ImgMdm, ImgUrl100 AS ImgSml, State, Remark, RegistId, RegistName, RegistDate, ChangeId, ChangeName, ChangeDate FROM shopion.tPrdProd WHERE ProdCode = #{pProdCode}
ORDER BY ImgCode ASC
